<style>
.ccs-directory-page main{max-width:none;padding:24px;min-width:0}.directory-head{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin-bottom:20px}.directory-head h1{font-size:25px}.directory-head p{font-size:12px;color:#9bb7aa;margin:5px 0}.directory-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0}.directory-stat{display:flex;align-items:center;gap:14px;padding:20px;border:1px solid #2e454c;border-radius:12px;background:#14262e;min-width:0}.directory-stat>span{display:grid;place-items:center;flex-shrink:0;width:43px;height:43px;background:#194137;color:#b7e8ca;border-radius:11px;font-size:20px}.directory-stat small{display:block;font-size:11px;color:#9eb9ac}.directory-stat strong{display:block;font-size:24px;color:#e3f0e6;margin-top:5px;overflow-wrap:anywhere}.directory-panel{border:1px solid #2e454c;border-radius:12px;background:#14262e;overflow:hidden;margin-bottom:20px}.directory-filter{display:flex;gap:12px;align-items:center;padding:15px;flex-wrap:wrap}.directory-filter>input{flex:1;min-width:200px}.directory-filter>select{max-width:300px}.directory-filter label{display:flex;gap:8px;align-items:center;margin:0;font-size:12px;white-space:nowrap}.directory-filter label input{width:auto}.directory-filter>*{font-size:12px}.directory-scroll{max-height:62vh;overflow:auto}.directory-table{min-width:850px}.directory-table th{position:sticky;top:0;z-index:1;background:#102128;color:#91ad9e;font-size:10px;text-transform:uppercase;letter-spacing:.06em}.directory-table td{padding:17px 15px;font-size:12px;border-bottom:1px solid #294148}.directory-table tr.selected td,.directory-table tbody tr:hover td{background:#1c343b}.directory-table small{display:block;margin-top:4px;color:#92b09f;font-size:10px}.directory-table .money{text-align:right;font-variant-numeric:tabular-nums}.directory-person{display:flex;align-items:center;gap:11px}.directory-avatar{display:grid;place-items:center;width:34px;height:34px;background:#174238;color:#b4e9c8;border-radius:50%;font-size:11px;flex-shrink:0;font-weight:850}.directory-badge{display:inline-block;padding:5px 10px;border-radius:16px;background:#1b4b3c;color:#a6e8c7;font-size:10px}.directory-badge.due{background:#4b3029;color:#ffb697}.directory-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:15px;color:#93b3a3;font-size:12px}.directory-dialog{width:min(800px,95vw);max-height:90dvh;overflow:auto;background:#10292b;color:#e4f4e8;border:1px solid #4d7560;border-radius:13px;padding:22px}.directory-dialog:not([open]){display:none}.directory-dialog::backdrop{background:#000a}.directory-dialog-head{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:20px}.directory-dialog-head h2{margin:0;font-size:21px}.directory-fields{display:grid;grid-template-columns:1fr 1fr;gap:13px}.directory-fields .wide{grid-column:1/-1}.directory-fields label{margin-top:0;font-size:12px}.directory-fields textarea{min-height:75px}.directory-vehicle-fields{border:1px solid #36594e;border-radius:10px;padding:15px;margin:16px 0}.directory-vehicle-fields:disabled{display:none}.directory-toggle{display:flex;align-items:center;gap:9px;margin-top:20px}.directory-toggle input{width:18px;height:18px}.directory-dialog-actions{display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap;margin-top:20px}.directory-extra{margin-top:18px}.directory-extra summary{cursor:pointer;margin-bottom:14px;color:#a8d1b9}.profile-info{padding:18px;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px}.profile-info small{display:block;font-size:11px;margin-bottom:5px}.profile-info strong{overflow-wrap:anywhere}.directory-section-title{padding:18px;margin:0;font-size:17px;border-bottom:1px solid #2e454c}.directory-table a{color:#c4e9cb}.directory-muted{color:#98b5a5}.directory-empty{padding:20px;text-align:center}.directory-table [data-directory-url]{cursor:pointer}.