@media(max-width:600px){.ccs-directory-page main{padding:14px}.directory-fields{grid-template-columns:1fr}.directory-fields .wide{grid-column:auto}.directory-dialog{padding:17px}.directory-summary{gap:10px}.directory-stat{padding:13px;gap:9px}.directory-stat>span{display:none}.directory-stat strong{font-size:20px}.directory-filter>select{max-width:none}.directory-dialog-actions button{flex:1}.directory-head h1{font-size:23px}}
